def find_gaps(bufs, tps):
    gaps = []
    for i in range(1, len(bufs)):
        t_prev, n_prev = bufs[i - 1]
        expected = t_prev + n_prev * tps
        d = bufs[i][0] - expected
        if d % tps:
            raise ValueError(f'misaligned timestamp at {i}')
        if d:
            gaps.append((i, d // tps))
    return gaps

