#include <cstdint>
#include <vector>
struct Buf { uint64_t t; uint32_t n; };   // t in ticks
// missing samples before each buffer (negative = overlap)
std::vector<int64_t> gaps(const std::vector<Buf>& b, uint64_t tps) {
    std::vector<int64_t> out;
    for (size_t i = 1; i < b.size(); ++i) {
        uint64_t expected = b[i-1].t + b[i-1].n * tps;
        uint64_t d = b[i].t - expected;
        if (d != 0) out.push_back(d / tps);
    }
    return out;
}

