#include <cstdint>
#include <stdexcept>
#include <utility>
#include <vector>

double estimate_ppm(const std::vector<std::pair<int64_t, int64_t>>& obs) {
    const size_t n = obs.size();
    if (n < 2) throw std::invalid_argument("need >= 2 points");
    const int64_t k0 = obs[0].first, l0 = obs[0].second;
    double mx = 0, my = 0;               // means of exact int64 offsets
    for (const auto& [k, l] : obs) { mx += double(k - k0); my += double(l - l0); }
    mx /= n; my /= n;
    double sxx = 0, sxy = 0;             // centered sums: no cancellation
    for (const auto& [k, l] : obs) {
        const double dx = double(k - k0) - mx, dy = double(l - l0) - my;
        sxx += dx * dx; sxy += dx * dy;
    }
    if (sxx == 0) throw std::invalid_argument("all k equal");
    return sxy / sxx * 1e6;              // fill samples per written sample -> ppm
}
